/**
 * Registers dist/sw.js (generated by scripts/build-pwa.mjs) in production web builds.
 * Updates never activate on their own (docs/04 §14.4): the UI gets `apply()` and calls it when no form is
 * being edited; the page reloads once the new worker takes control.
 */
export interface ServiceWorkerOptions {
  onUpdateAvailable?: (apply: () => void) => void;
}

export function registerServiceWorker(options: ServiceWorkerOptions = {}): void {
  if (process.env.NODE_ENV !== 'production' || typeof window === 'undefined' || !('serviceWorker' in navigator)) return;
  const container = navigator.serviceWorker;

  const offer = (worker: ServiceWorker) =>
    options.onUpdateAvailable?.(() => {
      let reloading = false;
      container.addEventListener('controllerchange', () => {
        if (reloading) return;
        reloading = true;
        window.location.reload();
      });
      worker.postMessage({ type: 'SKIP_WAITING' });
    });

  const start = async () => {
    try {
      const registration = await container.register('/sw.js', { scope: '/' });
      // A waiting worker only means "update" when a previous one controls the page.
      if (registration.waiting && container.controller) offer(registration.waiting);
      registration.addEventListener('updatefound', () => {
        const worker = registration.installing;
        worker?.addEventListener('statechange', () => {
          if (worker.state === 'installed' && container.controller) offer(worker);
        });
      });
      // Ask the browser not to evict local apps under storage pressure (it may refuse; docs/09 §14.5).
      if (navigator.storage?.persist && !(await navigator.storage.persisted())) await navigator.storage.persist();
    } catch (error) {
      console.warn('[kalam] service worker registration failed', error);
    }
  };

  if (document.readyState === 'complete') void start();
  else window.addEventListener('load', () => void start(), { once: true });
}
